reaction.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
    const conditionNames = [
        "Immobilized",
        "Impaired",
        "Jammed",
        "Lock On",
        "Shredded",
        "Slowed",
        "Stunned",
    ];

    return api.getAllEffects(reactorToken).some((e) => conditionNames.includes(e.name));
}

reaction.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const actor = reactorToken.actor;
    if (!actor || !item) return;

    const conditionNames = [
        "Immobilized",
        "Impaired",
        "Jammed",
        "Lock On",
        "Shredded",
        "Slowed",
        "Stunned",
    ];
    const superiorFrameConditions = ["Immobilized", "Slowed"];

    const conditionEffects = api
        .getAllEffects(reactorToken)
        .filter((e) => conditionNames.includes(e.name));

    const hasSuperiorFrame = actor.itemTypes.npc_feature.some(
        (i) => i.system.lid === "npc-rebake_npcf_superior_frame_ultra",
    );

    const chosenConditionEffect = await api.pickCard(conditionEffects, {
        description: "Choose a condition to clear.",
        item,
        label(effect) {
            if (hasSuperiorFrame && superiorFrameConditions.includes(effect.name)) {
                return `${effect.name} (Superior Frame usable)`;
            }

            return effect.name;
        },
        originToken: reactorToken,
        title: activationName,
    });
    if (!chosenConditionEffect) return;

    /** @type {Choices} */
    const choices = [];

    if (!conditionEffects.some((e) => e.name === "Impaired")) {
        choices.push({
            callback() {
                return api.applyEffectsToTokens({
                    duration: { label: "end", turns: 0 },
                    effectNames: ["impaired"],
                    tokens: [reactorToken],
                });
            },
            text: "become Impaired until the end of the turn",
        });
    }

    choices.push(
        {
            callback() {
                return api.executeDamageRoll(reactorToken, [reactorToken], 5, "Energy", item.name, {
                    paracausal: true,
                });
            },
            text: "take 5 energy damage (can't be reduced)",
        },
        {
            callback() {
                return actor.update({ "system.action_tracker.full": false });
            },
            text: "only have a quick action available",
        },
    );

    if (hasSuperiorFrame && superiorFrameConditions.includes(chosenConditionEffect.name)) {
        choices.push({
            callback() {
                return api.executeDamageRoll(reactorToken, [reactorToken], 4, "Heat", item.name);
            },
            text: "take 4 heat (through Superior Frame)",
        });
    }

    const result = await api.startChoiceCard({
        choices,
        description: `Choose how to clear "${chosenConditionEffect.name}"`,
        item,
        originToken: reactorToken,
        title: activationName,
    });
    if (!result) return;

    await api.deleteEffect(reactorToken, chosenConditionEffect);
}
